def _write_jsonl(path: Path, records: list) -> Path:
    with open(path, "w", encoding="utf-8") as f:
        for r in records:
            f.write(json.dumps(r) + "\n")
    return path


def _msg(role, content):
    return {
        "type": "response_item",
        "payload": {"type": "message", "role": role, "content": content},
    }


def _text_block(text):
